INSERT INTO feature VALUES('lsp-watched-files','editor','Watched files','language-server','implemented','ordinary',NULL,'A client with dynamic registration is asked at `initialized` to watch `**/*.gandr`; a change on disk rechecks and republishes only the held copies whose last closure named that path, a missing import''s path included, so writing the file heals its importer; the editor''s own copy of a changed file is never replaced from disk. A closure''s read of a file a watcher reports stands without a look at the disk until the watcher reports it; every other file is confirmed at each lay-out.','surface-lsp surface-dispatcher','crates/surface-lsp/src/server.rs crates/surface-dispatcher/src/component.rs',NULL,'#764');
